    QTabWidget, QFormLayout, QLineEdit, QGroupBox, QPlainTextEdit,
    QGridLayout, QSizePolicy, QComboBox, QDoubleSpinBox, QSpinBox, QListWidget, QListWidgetItem, QFileDialog, QApplication,
    QMenu,
    QToolTip,
    QMessageBox,
    QProgressBar,
    QDialog,
    QDialogButtonBox,
    QColorDialog,
    QAbstractItemView,
