    def _on_path_copy_badge_fail_hist_undo_bar_context(
            self, event=None) -> bool:
        """wave56: 徽章倒计时条右键 → 色阶热同步菜单."""
        try:
            menu = self._build_undo_color_scale_hot_sync_menu()
            self._last_path_copy_badge_fail_hist_undo_bar_menu = menu
            if getattr(self, '_path_copy_badge_fail_hist_undo_bar_menu_no_exec', False):
                self._last_path_copy_badge_fail_hist_undo_bar_menu_shown = True
                return True
            pos = None
            try:
                if event is not None and hasattr(event, 'globalPosition'):
                    pos = event.globalPosition().toPoint()
                elif event is not None and hasattr(event, 'globalPos'):
                    pos = event.globalPos()
            except Exception:
                pos = None
            if pos is None:
                bar = getattr(self, '_path_copy_badge_fail_hist_undo_bar', None)
                if bar is not None:
                    pos = bar.mapToGlobal(bar.rect().center())
                else:
                    pos = self.mapToGlobal(self.rect().center())
            menu.exec(pos)
            self._last_path_copy_badge_fail_hist_undo_bar_menu_shown = True
            return True
        except Exception:
            self._last_path_copy_badge_fail_hist_undo_bar_menu_shown = False
            return False

    def stale_prune_undo_color_custom_rgb(self) -> dict:
        """wave53–54: 自定义 RGB hi/mid/lo + α."""
        d = getattr(self, '_stale_prune_undo_color_custom', None)
        if not isinstance(d, dict):
            d = {'hi': '#3ecf8e', 'mid': '#f0c040', 'lo': '#e35d6a', 'alpha': 255}
            self._stale_prune_undo_color_custom = d
        try:
            alpha = int(d.get('alpha', 255))
        except Exception:
            alpha = 255
        alpha = max(40, min(255, alpha))
        out = {
            'hi': str(d.get('hi') or '#3ecf8e'),
            'mid': str(d.get('mid') or '#f0c040'),
            'lo': str(d.get('lo') or '#e35d6a'),
            'alpha': alpha,
        }
        return out

    def set_stale_prune_undo_color_custom_rgb(
            self, hi: str = None, mid: str = None, lo: str = None,
            alpha: int = None, *, persist: bool = True, apply: bool = True) -> dict:
        """wave53–54: 写入自定义 RGB/α 并可选切到 custom 预设."""
        cur = self.stale_prune_undo_color_custom_rgb()

        def _norm(v, fallback):
            s = str(v or fallback).strip()
            if not s.startswith('#'):
                s = '#' + s
            if len(s) not in (4, 7):
                return fallback
            return s.lower()

        cur['hi'] = _norm(hi if hi is not None else cur['hi'], '#3ecf8e')
        cur['mid'] = _norm(mid if mid is not None else cur['mid'], '#f0c040')
        cur['lo'] = _norm(lo if lo is not None else cur['lo'], '#e35d6a')
        if alpha is not None:
            try:
                cur['alpha'] = max(40, min(255, int(alpha)))
            except Exception:
                pass
        self._stale_prune_undo_color_custom = dict(cur)
        if persist:
            try:
                s = self._host_settings()
                s.setValue('host/stalePruneUndoColorCustomHi', cur['hi'])
                s.setValue('host/stalePruneUndoColorCustomMid', cur['mid'])
                s.setValue('host/stalePruneUndoColorCustomLo', cur['lo'])
                s.setValue('host/stalePruneUndoColorCustomAlpha', int(cur['alpha']))
            except Exception:
                pass
        if apply:
            try:
                self.set_stale_prune_undo_color_scale_preset('custom')
            except Exception:
                pass
        self._last_stale_prune_undo_color_custom = dict(cur)
        return dict(cur)

    def set_stale_prune_undo_color_custom_alpha(
            self, alpha: int = 255, *, persist: bool = True, apply: bool = True) -> int:
        """wave54: 单独设置自定义色阶 α."""
        got = self.set_stale_prune_undo_color_custom_rgb(
            alpha=alpha, persist=persist, apply=apply)
        try:
            self._last_stale_prune_undo_color_custom_alpha_spin_default = int(
                got.get('alpha', 255))
        except Exception:
            pass
        return int(got.get('alpha', 255))

    def set_stale_prune_undo_color_custom_hex(
            self, hex_spec: str = '', *, which: str = 'hi',
            persist: bool = True, apply: bool = True) -> dict:
        """wave63: 自定义色阶 hex 入口（which=hi|mid|lo|all；all 用逗号分隔）."""
        spec = str(hex_spec or '').strip()
        which = str(which or 'hi').strip().lower()
        cur = dict(self.stale_prune_undo_color_custom_rgb())
        if which == 'all':
            parts = [x.strip() for x in spec.replace(';', ',').split(',') if x.strip()]
            keys = ('hi', 'mid', 'lo')
            for i, part in enumerate(parts[:3]):
                hx = part if part.startswith('#') else '#' + part
                try:
                    qc = QColor(hx)
                    if qc.isValid():
                        cur[keys[i]] = qc.name()
                except Exception:
                    pass
        else:
            if which not in ('hi', 'mid', 'lo'):
                which = 'hi'
            hx = spec if spec.startswith('#') else ('#' + spec if spec else '')
            if hx:
                try:
                    qc = QColor(hx)
                    if qc.isValid():
                        cur[which] = qc.name()
                except Exception:
                    pass
        got = self.set_stale_prune_undo_color_custom_rgb(
            cur.get('hi'), cur.get('mid'), cur.get('lo'),
            alpha=cur.get('alpha'), persist=persist, apply=apply)
        try:
            self.set_stale_prune_undo_color_scale_preset('custom', persist=persist)
        except Exception:
            pass
        self._last_stale_prune_undo_color_custom_hex = {
            'which': which, 'spec': spec,
            'rgb': dict(got) if isinstance(got, dict) else cur}
        return got if isinstance(got, dict) else cur

    def prompt_stale_prune_undo_color_custom_hex(
            self, which: str = 'hi', hexv: str = None) -> str:
        """wave63: 弹出/烟雾路径输入自定义色阶 hex."""
        which = str(which or 'hi').strip().lower()
        if which not in ('hi', 'mid', 'lo', 'all'):
            which = 'hi'
        cur = self.stale_prune_undo_color_custom_rgb()
        default = cur.get(which if which != 'all' else 'hi', '#3ecf8e')
        if which == 'all':
            default = (
                f"{cur.get('hi', '#3ecf8e')},"
                f"{cur.get('mid', '#f0c040')},"
                f"{cur.get('lo', '#e35d6a')}")
        text = hexv
        if text is None:
            if getattr(self, '_stale_prune_undo_custom_hex_no_dialog', False):
                text = str(getattr(
                    self, '_stale_prune_undo_custom_hex_smoke', '') or default)
            else:
                try:
                    text, ok = QInputDialog.getText(
                        self, '自定义色阶 hex',
                        f'输入 {which} hex（all 用逗号分隔 hi,mid,lo）',
                        text=str(default))
                    if not ok:
                        self._last_stale_prune_undo_color_custom_hex_prompt = ''
                        return ''
                except Exception:
                    text = default
        text = str(text or '').strip()
        if not text:
            self._last_stale_prune_undo_color_custom_hex_prompt = ''
            return ''
        got = self.set_stale_prune_undo_color_custom_hex(text, which=which)
        out = (got.get(which if which != 'all' else 'hi', text)
               if isinstance(got, dict) else text)
        self._last_stale_prune_undo_color_custom_hex_prompt = out
        try:
            self._flash_host_toast(
                f'色阶 hex · {which} · {out}', kind='ok', ms=1100)
        except Exception:
            pass
        return out

    def pick_stale_prune_undo_color_custom_hex_eyedropper(
            self, which: str = 'hi', *, persist: bool = True) -> str:
        """wave64: 色阶 hex 吸管（QColorDialog / 烟雾路径）."""
        which = str(which or 'hi').strip().lower()
        if which not in ('hi', 'mid', 'lo'):
            which = 'hi'
        cur = self.stale_prune_undo_color_custom_rgb()
        start = str(cur.get(which, '#3ecf8e'))
        picked = ''
        if getattr(self, '_stale_prune_undo_eyedropper_no_dialog', False):
            picked = str(getattr(
                self, '_stale_prune_undo_eyedropper_smoke', '') or '#ee44aa').strip()
        else:
            try:
                qc = QColorDialog.getColor(
                    QColor(start), self, f'吸管 · {which}')
                if qc is not None and qc.isValid():
                    picked = qc.name()
            except Exception:
                picked = ''
        if not picked:
            self._last_stale_prune_undo_color_eyedropper = ''
            return ''
        if not picked.startswith('#'):
            picked = '#' + picked
        try:
            c = QColor(picked)
            if c.isValid():
                picked = c.name()
            else:
                self._last_stale_prune_undo_color_eyedropper = ''
                return ''
        except Exception:
            self._last_stale_prune_undo_color_eyedropper = ''
            return ''
        self.set_stale_prune_undo_color_custom_hex(
            picked, which=which, persist=persist)
        self._last_stale_prune_undo_color_eyedropper = picked
        self._last_stale_prune_undo_color_eyedropper_which = which
        try:
            self.remember_stale_prune_undo_eyedropper_history(picked)
        except Exception:
            pass
        try:
            edit = getattr(self, '_last_undo_color_scale_custom_hex_edit', None)
            if edit is not None:
                edit.setText(picked)
        except Exception:
            pass
        try:
            self._paint_undo_color_scale_preview_bar()
        except Exception:
            pass
        try:
            self._flash_host_toast(
                f'吸管 · {which} · {picked}', kind='ok', ms=1000)
        except Exception:
            pass
        return picked

    def stale_prune_undo_eyedropper_history(self) -> list:
        """wave66: 吸管历史色（最多 12）."""
        raw = getattr(self, '_stale_prune_undo_eyedropper_history', None)
        if not isinstance(raw, list):
            raw = []
            self._stale_prune_undo_eyedropper_history = raw
        out = []
        for x in raw:
            hx = str(x or '').strip()
            if not hx:
                continue
            if not hx.startswith('#'):
                hx = '#' + hx
            try:
                c = QColor(hx)
                if c.isValid():
                    out.append(c.name())
            except Exception:
                pass
        return out[:12]

    def remember_stale_prune_undo_eyedropper_history(
            self, hexv: str = '', *, persist: bool = True) -> list:
        """wave66: 记一笔吸管历史（去重置顶）."""
        hexv = str(hexv or '').strip()
        if not hexv:
            return self.stale_prune_undo_eyedropper_history()
        if not hexv.startswith('#'):
            hexv = '#' + hexv
        try:
            c = QColor(hexv)
            if not c.isValid():
                return self.stale_prune_undo_eyedropper_history()
            hexv = c.name()
        except Exception:
            return self.stale_prune_undo_eyedropper_history()
        cur = [x for x in self.stale_prune_undo_eyedropper_history() if x != hexv]
        cur.insert(0, hexv)
        cur = cur[:12]
        self._stale_prune_undo_eyedropper_history = cur
        if persist:
            try:
                self._host_settings().setValue(
                    'host/stalePruneUndoEyedropperHistory', list(cur))
            except Exception:
                pass
        self._last_stale_prune_undo_eyedropper_history = list(cur)
        return list(cur)

