    def detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(
            self, undo_key: str = None, redo_key: str = None) -> list:
        """wave74: 吸史撤序/重序快捷冲突检测 → [{key, role, reason}, ...]."""
        try:
            u = QKeySequence(str(
                undo_key if undo_key is not None
                else self.stale_prune_undo_eyedropper_history_order_undo_shortcut()
            )).toString(QKeySequence.SequenceFormat.PortableText)
        except Exception:
            u = str(undo_key or self.stale_prune_undo_eyedropper_history_order_undo_shortcut())
        try:
            r = QKeySequence(str(
                redo_key if redo_key is not None
                else self.stale_prune_undo_eyedropper_history_order_redo_shortcut()
            )).toString(QKeySequence.SequenceFormat.PortableText)
        except Exception:
            r = str(redo_key or self.stale_prune_undo_eyedropper_history_order_redo_shortcut())
        u = str(u or '').strip() or 'Ctrl+Shift+Z'
        r = str(r or '').strip() or 'Ctrl+Shift+Y'
        conflicts = []
        if u == r:
            conflicts.append({'key': u, 'role': 'both', 'reason': '撤序/重序键相同'})
        reserved = {
            'Ctrl+C': '复制', 'Ctrl+V': '粘贴', 'Ctrl+X': '剪切',
            'Ctrl+Z': '撤销', 'Ctrl+Y': '重做', 'Ctrl+A': '全选',
            'Ctrl+S': '保存', 'Ctrl+O': '打开', 'Ctrl+N': '新建',
            'Ctrl+W': '关闭', 'Ctrl+Q': '退出', 'Ctrl+F': '查找',
            'Alt+F4': '关闭窗口',
            'Ctrl+[': '钉上限−', 'Ctrl+]': '钉上限+',
        }
        for key, role in ((u, 'undo'), (r, 'redo')):
            if key in reserved:
                conflicts.append({
                    'key': key, 'role': role,
                    'reason': f'保留快捷 · {reserved[key]}',
                })
        # collide with pin max keys
        try:
            pin_d = self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_dec_key()
            pin_i = self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_inc_key()
            for key, role in ((u, 'undo'), (r, 'redo')):
                if key == pin_d:
                    conflicts.append({
                        'key': key, 'role': role, 'reason': '与钉上限−冲突',
                    })
                if key == pin_i:
                    conflicts.append({
                        'key': key, 'role': role, 'reason': '与钉上限+冲突',
                    })
        except Exception:
            pass
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflicts = list(conflicts)
        return list(conflicts)


    def suggest_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix(
            self, undo_key: str = None, redo_key: str = None) -> dict:
        """wave75: 为冲突快捷建议一键改键候选."""
        try:
            u = QKeySequence(str(
                undo_key if undo_key is not None
                else self.stale_prune_undo_eyedropper_history_order_undo_shortcut()
            )).toString(QKeySequence.SequenceFormat.PortableText)
        except Exception:
            u = str(undo_key or self.stale_prune_undo_eyedropper_history_order_undo_shortcut())
        try:
            r = QKeySequence(str(
                redo_key if redo_key is not None
                else self.stale_prune_undo_eyedropper_history_order_redo_shortcut()
            )).toString(QKeySequence.SequenceFormat.PortableText)
        except Exception:
            r = str(redo_key or self.stale_prune_undo_eyedropper_history_order_redo_shortcut())
        u = str(u or '').strip() or 'Ctrl+Shift+Z'
        r = str(r or '').strip() or 'Ctrl+Shift+Y'
        conflicts = self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(u, r)
        if not conflicts:
            out = {
                'needed': False, 'undo': u, 'redo': r,
                'suggested_undo': u, 'suggested_redo': r, 'conflicts': [],
            }
            self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix = dict(out)
            return dict(out)
        candidates_u = [
            'Ctrl+Alt+Z', 'Ctrl+Shift+Alt+Z', 'Alt+Shift+Z',
            'Meta+Shift+Z', 'Ctrl+Alt+U', 'Ctrl+Shift+Backspace',
        ]
        candidates_r = [
            'Ctrl+Alt+Y', 'Ctrl+Shift+Alt+Y', 'Alt+Shift+Y',
            'Meta+Shift+Y', 'Ctrl+Alt+R', 'Ctrl+Shift+Delete',
        ]
        # also try defaults if current is conflicted
        candidates_u = ['Ctrl+Shift+Z'] + candidates_u
        candidates_r = ['Ctrl+Shift+Y'] + candidates_r
        su = u
        sr = r
        roles = {c.get('role') for c in conflicts}
        if 'both' in roles or 'undo' in roles or any(
                c.get('role') == 'both' for c in conflicts):
            for cand in candidates_u:
                try:
                    cand = QKeySequence(cand).toString(
                        QKeySequence.SequenceFormat.PortableText) or cand
                except Exception:
                    pass
                if not self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(cand, r if sr == r else sr):
                    # provisional — still need redo free vs cand
                    su = cand
                    break
                trial = self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(cand, 'Ctrl+Alt+Y')
                # if only redo side issues with placeholder, still take cand for undo
                if not any(x.get('role') in ('undo', 'both') for x in trial):
                    su = cand
                    break
        if 'both' in roles or 'redo' in roles:
            for cand in candidates_r:
                try:
                    cand = QKeySequence(cand).toString(
                        QKeySequence.SequenceFormat.PortableText) or cand
                except Exception:
                    pass
                if cand == su:
                    continue
                trial = self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(su, cand)
                if not trial:
                    sr = cand
                    break
        # final ensure pair clean — brute
        if self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(su, sr):
            for cu in candidates_u:
                for cr in candidates_r:
                    if cu == cr:
                        continue
                    try:
                        cu2 = QKeySequence(cu).toString(
                            QKeySequence.SequenceFormat.PortableText) or cu
                        cr2 = QKeySequence(cr).toString(
                            QKeySequence.SequenceFormat.PortableText) or cr
                    except Exception:
                        cu2, cr2 = cu, cr
                    if not self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(cu2, cr2):
                        su, sr = cu2, cr2
                        break
                else:
                    continue
                break
        out = {
            'needed': True,
            'undo': u, 'redo': r,
            'suggested_undo': su, 'suggested_redo': sr,
            'conflicts': list(conflicts),
            'changed': (su != u) or (sr != r),
        }
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix = dict(out)
        return dict(out)


    def list_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidates(
            self, undo_key: str = None, redo_key: str = None, *, limit: int = 6) -> list:
        """wave76: 吸史改键候选列表 [(undo, redo, clean), ...]."""
        try:
            lim = max(1, min(12, int(limit)))
        except Exception:
            lim = 6
        try:
            u0 = QKeySequence(str(
                undo_key if undo_key is not None
                else self.stale_prune_undo_eyedropper_history_order_undo_shortcut()
            )).toString(QKeySequence.SequenceFormat.PortableText)
        except Exception:
            u0 = str(undo_key or self.stale_prune_undo_eyedropper_history_order_undo_shortcut())
        try:
            r0 = QKeySequence(str(
                redo_key if redo_key is not None
                else self.stale_prune_undo_eyedropper_history_order_redo_shortcut()
            )).toString(QKeySequence.SequenceFormat.PortableText)
        except Exception:
            r0 = str(redo_key or self.stale_prune_undo_eyedropper_history_order_redo_shortcut())
        u0 = str(u0 or '').strip() or 'Ctrl+Shift+Z'
        r0 = str(r0 or '').strip() or 'Ctrl+Shift+Y'
        cand_u = [
            'Ctrl+Shift+Z', 'Ctrl+Alt+Z', 'Ctrl+Shift+Alt+Z', 'Alt+Shift+Z',
            'Meta+Shift+Z', 'Ctrl+Alt+U', 'Ctrl+Shift+Backspace', 'Alt+Z',
        ]
        cand_r = [
            'Ctrl+Shift+Y', 'Ctrl+Alt+Y', 'Ctrl+Shift+Alt+Y', 'Alt+Shift+Y',
            'Meta+Shift+Y', 'Ctrl+Alt+R', 'Ctrl+Shift+Delete', 'Alt+Y',
        ]
        out = []
        seen = set()
        for cu in cand_u:
            for cr in cand_r:
                if cu == cr:
                    continue
                try:
                    cu2 = QKeySequence(cu).toString(
                        QKeySequence.SequenceFormat.PortableText) or cu
                    cr2 = QKeySequence(cr).toString(
                        QKeySequence.SequenceFormat.PortableText) or cr
                except Exception:
                    cu2, cr2 = cu, cr
                key = (cu2, cr2)
                if key in seen:
                    continue
                seen.add(key)
                conf = self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(cu2, cr2)
                if conf:
                    continue
                out.append({'undo': cu2, 'redo': cr2, 'clean': True,
                            'label': f'{cu2} / {cr2}',
                            'current': (cu2 == u0 and cr2 == r0)})
                if len(out) >= lim:
                    break
            if len(out) >= lim:
                break
        # ensure suggested pair is first if present
        try:
            sug = self.suggest_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix(u0, r0)
            su = str(sug.get('suggested_undo') or '')
            sr = str(sug.get('suggested_redo') or '')
            if su and sr:
                pref = {'undo': su, 'redo': sr, 'clean': True,
                        'label': f'{su} / {sr} · 建议',
                        'current': (su == u0 and sr == r0), 'suggested': True}
                out = [x for x in out if not (x['undo'] == su and x['redo'] == sr)]
                out.insert(0, pref)
                out = out[:lim]
        except Exception:
            pass
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidates = list(out)
        return list(out)



    def confirm_trial_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate(
            self, *, persist: bool = True) -> dict:
        """wave78–79: 确认悬停试键（应用最近 trial tip 的撤/重键；可撤销）."""
        trial = dict(getattr(
            self,
            '_last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_trial',
            {}) or {})
        u = str(trial.get('undo') or '').strip()
        r = str(trial.get('redo') or '').strip()
        if not u or not r:
            self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirmed = {
                'applied': False, 'reason': 'no_trial',
            }
            try:
                self._flash_host_toast('试键 · 无悬停候选可确认', kind='warn', ms=900)
            except Exception:
                pass
            return {'applied': False, 'undo': u, 'redo': r}
        try:
            before_u = str(self.stale_prune_undo_eyedropper_history_order_undo_shortcut() or '')
            before_r = str(self.stale_prune_undo_eyedropper_history_order_redo_shortcut() or '')
        except Exception:
            before_u, before_r = '', ''
        try:
            self.set_stale_prune_undo_eyedropper_history_order_shortcuts(
                u, r, persist=persist, rebind=True, warn=False)
            applied = True
        except Exception:
            applied = False
        if applied:
            stack = list(getattr(
                self,
                '_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo',
                []) or [])
            stack.append({
                'before': (before_u, before_r),
                'after': (u, r),
                'tip': str(trial.get('tip') or ''),
            })
            if len(stack) > 16:
                stack = stack[-16:]
            self._stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo = stack
        out = {
            'applied': bool(applied), 'undo': u, 'redo': r,
            'clean': bool(trial.get('clean')),
            'conflicts': list(trial.get('conflicts') or []),
            'tip': str(trial.get('tip') or ''),
            'before': (before_u, before_r),
            'undo_depth': len(getattr(
                self,
                '_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo',
                []) or []),
        }
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirmed = dict(out)
        try:
            self._refresh_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo_depth_ui()
        except Exception:
            pass
        try:
            self._flash_host_toast(
                f'试键已确认 · 撤 {u} / 重 {r} · 可撤销',
                kind='ok' if applied else 'warn', ms=1100)
        except Exception:
            pass
        return dict(out)


    def stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo_import_conflict_strategy(
            self) -> str:
        """wave84: 试键撤栈导入冲突策略 replace|merge|skip|ask."""
        cur = getattr(
            self,
            '_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo_import_conflict',
            None)
        if cur in ('replace', 'merge', 'skip', 'ask'):
            return str(cur)
        try:
            v = str(self._host_settings().value(
                'host/stalePruneUndoEyedropperHistoryOrderShortcutConflictFixCandidateConfirmUndoImportConflict',
                'replace') or 'replace').strip().lower()
        except Exception:
            v = 'replace'
        if v not in ('replace', 'merge', 'skip', 'ask'):
            v = 'replace'
        self._stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo_import_conflict = v
        return v

    def set_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo_import_conflict_strategy(
            self, strategy: str = 'replace', *, persist: bool = True) -> str:
        """wave84: 设定试键撤栈导入冲突策略."""
        v = str(strategy or 'replace').strip().lower()
        if v not in ('replace', 'merge', 'skip', 'ask'):
            v = 'replace'
