    def undo_confirm_trial_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate(
            self, *, persist: bool = True) -> dict:
        """wave79: 撤销最近一次试键确认."""
        stack = list(getattr(
            self,
            '_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo',
            []) or [])
        if not stack:
            self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undone = {
                'undone': False, 'undo_depth': 0,
            }
            try:
                self._flash_host_toast('试键确认 · 无可撤销', kind='warn', ms=900)
            except Exception:
                pass
            return {'undone': False, 'undo': '', 'redo': ''}
        entry = stack.pop()
        self._stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo = stack
        before = entry.get('before') or ('', '')
        try:
            bu, br = str(before[0] or ''), str(before[1] or '')
        except Exception:
            bu, br = '', ''
        try:
            if bu and br:
                self.set_stale_prune_undo_eyedropper_history_order_shortcuts(
                    bu, br, persist=persist, rebind=True, warn=False)
                ok = True
            else:
                ok = False
        except Exception:
            ok = False
        out = {
            'undone': bool(ok), 'undo': bu, 'redo': br,
            'after': entry.get('after'),
            'undo_depth': len(stack),
        }
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undone = dict(out)
        try:
            self._refresh_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo_depth_ui(len(stack))
        except Exception:
            pass
        try:
            self._flash_host_toast(
                f'试键确认已撤销 · 撤 {bu} / 重 {br}' if ok else '试键确认撤销失败',
                kind='ok' if ok else 'warn', ms=1100)
        except Exception:
            pass
        return dict(out)


    def trial_tip_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate(
            self, undo_key: str = '', redo_key: str = '', *, index: int = -1) -> str:
        """wave77: 吸史候选悬停试键 tip（不改键）."""
        u = str(undo_key or '').strip()
        r = str(redo_key or '').strip()
        if (not u or not r) and index >= 0:
            try:
                cands = self.list_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidates()
                row = cands[int(index)]
                u = str(row.get('undo') or u)
                r = str(row.get('redo') or r)
            except Exception:
                pass
        cur_u = ''
        cur_r = ''
        try:
            cur_u = str(self.stale_prune_undo_eyedropper_history_order_undo_shortcut() or '')
            cur_r = str(self.stale_prune_undo_eyedropper_history_order_redo_shortcut() or '')
        except Exception:
            pass
        conf = []
        try:
            conf = self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(u, r)
        except Exception:
            conf = []
        clean = '干净' if not conf else f'仍冲×{len(conf)}'
        tip = f'试键 · 撤 {u or "?"} / 重 {r or "?"} · {clean}'
        if cur_u or cur_r:
            tip += f' · 现 {cur_u}/{cur_r}'
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_trial_tip = tip
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_trial = {
            'undo': u, 'redo': r, 'clean': not conf, 'conflicts': list(conf or []), 'tip': tip,
        }
        return tip

    def show_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_menu(
            self, global_pos=None, *, persist: bool = True) -> int:
        """wave76: 弹出吸史改键候选菜单；返回选中条数(0/1)."""
        if getattr(self, '_eyedropper_history_order_shortcut_fix_menu_no_exec', False):
            cands = self.list_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidates()
            self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_menu = {
                'candidates': list(cands), 'executed': False,
            }
            smoke = getattr(self, '_eyedropper_history_order_shortcut_fix_menu_smoke_index', None)
            if smoke is not None and cands:
                try:
                    idx = int(smoke)
                except Exception:
                    idx = 0
                idx = max(0, min(len(cands) - 1, idx))
                row = cands[idx]
                self.set_stale_prune_undo_eyedropper_history_order_shortcuts(
                    row['undo'], row['redo'], persist=persist, rebind=True, warn=False)
                self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_menu['applied'] = row
                return 1
            if getattr(self, '_eyedropper_history_order_shortcut_fix_menu_smoke_confirm_trial', False):
                out = self.confirm_trial_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate(
                    persist=persist)
                self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_menu['confirmed'] = out
                return 1 if out.get('applied') else 0
            if getattr(self, '_eyedropper_history_order_shortcut_fix_menu_smoke_undo_confirm_trial', False):
                out = self.undo_confirm_trial_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate(
                    persist=persist)
                self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_menu['confirm_undone'] = out
                return 1 if out.get('undone') else 0
            return 0
        cands = self.list_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidates()
        menu = QMenu(self)
        menu.setObjectName('hostUndoColorScaleEyedropperHistoryOrderShortcutFixMenu')
        menu.setProperty('isUndoEyedropperHistoryOrderShortcutFixMenu', True)
        if not cands:
            act = QAction('无可用干净候选', menu)
            act.setEnabled(False)
            menu.addAction(act)
        applied = {'n': 0}
        for i, row in enumerate(cands):
            lab = str(row.get('label') or f"{row.get('undo')} / {row.get('redo')}")
            if row.get('suggested'):
                lab = '★ ' + lab
            elif row.get('current'):
                lab = '● ' + lab
            else:
                lab = '○ ' + lab
            act = QAction(lab, menu)
            act.setProperty('isUndoEyedropperHistoryOrderShortcutFixCandidate', True)
            act.setProperty('eyedropperHistoryOrderShortcutFixUndo', row.get('undo'))
            act.setProperty('eyedropperHistoryOrderShortcutFixRedo', row.get('redo'))
            act.setProperty('eyedropperHistoryOrderShortcutFixIndex', int(i))
            def _apply(_=False, uu=row.get('undo'), rr=row.get('redo'), ap=applied):
                self.set_stale_prune_undo_eyedropper_history_order_shortcuts(
                    uu, rr, persist=persist, rebind=True, warn=False)
                ap['n'] = 1
            act.triggered.connect(_apply)
            def _hover(_checked=False, uu=row.get('undo'), rr=row.get('redo'), ii=i, _act=act):
                try:
                    tip = self.trial_tip_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate(
                        uu, rr, index=ii)
                    try:
                        _act.setToolTip(tip)
                        _act.setStatusTip(tip)
                        menu.setToolTip(tip)
                    except Exception:
                        pass
                except Exception:
                    pass
            try:
                act.hovered.connect(_hover)
            except Exception:
                pass
            menu.addAction(act)
        menu.addSeparator()
        act_confirm = QAction('确认悬停试键', menu)
        act_confirm.setProperty('isUndoEyedropperHistoryOrderShortcutFixConfirmTrial', True)
        act_confirm.triggered.connect(
            lambda *_: self.confirm_trial_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate(
                persist=persist))
        menu.addAction(act_confirm)
        _uc = len(getattr(
            self,
            '_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate_confirm_undo',
            []) or [])
        act_confirm_undo = QAction(f'撤销试键确认({_uc})' if _uc else '撤销试键确认', menu)
        act_confirm_undo.setEnabled(_uc > 0)
        act_confirm_undo.setProperty('isUndoEyedropperHistoryOrderShortcutFixConfirmTrialUndo', True)
        act_confirm_undo.triggered.connect(
            lambda *_: self.undo_confirm_trial_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_candidate(
                persist=persist))
        menu.addAction(act_confirm_undo)
        act_auto = QAction('一键建议改键', menu)
        act_auto.triggered.connect(
            lambda *_: self.fix_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(
                persist=persist))
        menu.addAction(act_auto)
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix_menu = menu
        try:
            if global_pos is not None:
                menu.exec(global_pos)
            else:
                btn = getattr(
                    self, '_last_undo_color_scale_eyedropper_history_order_shortcut_fix_btn', None)
                if btn is not None:
                    menu.exec(btn.mapToGlobal(btn.rect().bottomLeft()))
                else:
                    menu.exec()
        except Exception:
            pass
        return int(applied.get('n') or 0)

    def fix_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(
            self, *, persist: bool = True, rebind: bool = True) -> tuple:
        """wave75: 一键改键消除吸史快捷冲突."""
        sug = self.suggest_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix()
        su = str(sug.get('suggested_undo') or 'Ctrl+Shift+Z')
        sr = str(sug.get('suggested_redo') or 'Ctrl+Shift+Y')
        out = self.set_stale_prune_undo_eyedropper_history_order_shortcuts(
            su, sr, persist=persist, rebind=rebind, warn=False)
        left = self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(out[0], out[1])
        self._last_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fixed = {
            'keys': out, 'remaining': list(left), 'suggested': dict(sug),
        }
        try:
            if left:
                self._flash_host_toast(
                    f'改键仍有冲突 · {self.format_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(left)}',
                    kind='warn', ms=1400)
            else:
                self._flash_host_toast(
                    f'已改键 · {out[0]} / {out[1]}', kind='ok', ms=1100)
        except Exception:
            pass
        try:
            btn = getattr(
                self, '_last_undo_color_scale_eyedropper_history_order_shortcut_fix_btn', None)
            if btn is not None:
                btn.setEnabled(bool(left))
                btn.setProperty('eyedropperHistoryOrderShortcutConflictCount', int(len(left)))
        except Exception:
            pass
        return out

    def format_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(
            self, conflicts=None) -> str:
        """wave74: 冲突文案."""
        rows = conflicts
        if rows is None:
            rows = self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts()
        if not rows:
            return ''
        parts = [f"{c.get('key','?')}({c.get('reason','')})" for c in rows]
        return '；'.join(parts)

    def set_stale_prune_undo_eyedropper_history_order_shortcuts(
            self, undo_key: str = '', redo_key: str = '', *,
            persist: bool = True, rebind: bool = True, warn: bool = True) -> tuple:
        """wave73–74: 设定吸史撤序/重序快捷键（含冲突检测）."""
        u = str(undo_key or '').strip() or self.stale_prune_undo_eyedropper_history_order_undo_shortcut()
        r = str(redo_key or '').strip() or self.stale_prune_undo_eyedropper_history_order_redo_shortcut()
        try:
            u = QKeySequence(u).toString(QKeySequence.SequenceFormat.PortableText) or u
        except Exception:
            pass
        try:
            r = QKeySequence(r).toString(QKeySequence.SequenceFormat.PortableText) or r
        except Exception:
            pass
        if not u:
            u = 'Ctrl+Shift+Z'
        if not r:
            r = 'Ctrl+Shift+Y'
        self._stale_prune_undo_eyedropper_history_order_undo_shortcut = u
        self._stale_prune_undo_eyedropper_history_order_redo_shortcut = r
        if persist:
            try:
                s = self._host_settings()
                s.setValue('host/stalePruneUndoEyedropperHistoryOrderUndoShortcut', u)
                s.setValue('host/stalePruneUndoEyedropperHistoryOrderRedoShortcut', r)
            except Exception:
                pass
        if rebind:
            try:
                self._ensure_eyedropper_history_order_shortcuts(force=True)
            except Exception:
                pass
            try:
                bu = getattr(self, '_last_undo_color_scale_eyedropper_history_undo_order_btn', None)
                br = getattr(self, '_last_undo_color_scale_eyedropper_history_redo_order_btn', None)
                bk = getattr(self, '_last_undo_color_scale_eyedropper_history_order_shortcut_cfg_btn', None)
                if bu is not None:
                    bu.setShortcut(QKeySequence(u))
                    bu.setToolTip(f'撤销最近一次历史色拖拽落序 · {u}')
                    bu.setProperty('eyedropperHistoryOrderUndoShortcut', u)
                if br is not None:
                    br.setShortcut(QKeySequence(r))
                    br.setToolTip(f'重做最近一次被撤销的历史色落序 · {r}')
                    br.setProperty('eyedropperHistoryOrderRedoShortcut', r)
                if bk is not None:
                    bk.setToolTip(f'自定义吸史撤序/重序快捷 · 当前 {u} / {r}')
            except Exception:
                pass
        self._last_eyedropper_history_order_undo_shortcut = u
        self._last_eyedropper_history_order_redo_shortcut = r
        conf = []
        try:
            conf = self.detect_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(u, r)
        except Exception:
            conf = []
        tip_extra = ''
        if conf:
            tip_extra = self.format_stale_prune_undo_eyedropper_history_order_shortcut_conflicts(conf)
            try:
                bk = getattr(self, '_last_undo_color_scale_eyedropper_history_order_shortcut_cfg_btn', None)
                if bk is not None:
                    bk.setProperty('eyedropperHistoryOrderShortcutConflict', True)
                    bk.setStyleSheet('font-size:9px;padding:0 4px;color:#e6a23c;')
                    bk.setToolTip(
                        f'自定义吸史撤序/重序快捷 · 当前 {u} / {r}\n⚠ {tip_extra}')
            except Exception:
                pass
        else:
            try:
                bk = getattr(self, '_last_undo_color_scale_eyedropper_history_order_shortcut_cfg_btn', None)
                if bk is not None:
                    bk.setProperty('eyedropperHistoryOrderShortcutConflict', False)
                    bk.setStyleSheet('font-size:9px;padding:0 4px;')
                    bk.setToolTip(f'自定义吸史撤序/重序快捷 · 当前 {u} / {r}')
            except Exception:
                pass
        try:
            bf = getattr(
                self, '_last_undo_color_scale_eyedropper_history_order_shortcut_fix_btn', None)
            if bf is not None:
                bf.setEnabled(bool(conf))
                bf.setProperty('eyedropperHistoryOrderShortcutConflictCount', int(len(conf)))
                if conf:
                    bf.setStyleSheet('font-size:9px;padding:0 4px;color:#f0a020;')
                    try:
                        sug = self.suggest_stale_prune_undo_eyedropper_history_order_shortcut_conflict_fix(u, r)
                        bf.setToolTip(
                            f"一键改键消冲突 · {tip_extra} → "
                            f"{sug.get('suggested_undo')}/{sug.get('suggested_redo')}")
                    except Exception:
                        bf.setToolTip(f'一键改键消冲突 · {tip_extra}')
                else:
                    bf.setStyleSheet('font-size:9px;padding:0 4px;')
                    bf.setToolTip('一键改键消冲突 · 当前无冲突')
        except Exception:
            pass
        try:
            if warn and conf:
                self._flash_host_toast(
                    f'吸史快捷冲突 · {tip_extra}', kind='warn', ms=1400)
            else:
                self._flash_host_toast(f'吸史快捷 · 撤{u} / 重{r}', kind='ok', ms=1100)
        except Exception:
            pass
        return (u, r)

    def reset_stale_prune_undo_eyedropper_history_order_shortcuts(
            self, *, persist: bool = True) -> tuple:
        """wave73: 重置吸史重序快捷为默认."""
        return self.set_stale_prune_undo_eyedropper_history_order_shortcuts(
            'Ctrl+Shift+Z', 'Ctrl+Shift+Y', persist=persist, rebind=True)

    def prompt_stale_prune_undo_eyedropper_history_order_shortcuts(
            self, *, persist: bool = True) -> tuple:
        """wave73: 对话框自定义吸史撤序/重序快捷."""
        cur = (
            f"{self.stale_prune_undo_eyedropper_history_order_undo_shortcut()},"
            f"{self.stale_prune_undo_eyedropper_history_order_redo_shortcut()}"
        )
        if getattr(self, '_eyedropper_history_order_shortcuts_no_dialog', False):
            smoke = getattr(self, '_eyedropper_history_order_shortcuts_smoke', None)
            text = str(smoke if smoke is not None else cur)
            ok = True
        else:
            text, ok = QInputDialog.getText(
                self, '吸史重序快捷键',
                '输入 撤序,重序 两键（如 Ctrl+Shift+Z,Ctrl+Shift+Y）:',
                text=cur)
        if not ok:
            return (
                self.stale_prune_undo_eyedropper_history_order_undo_shortcut(),
                self.stale_prune_undo_eyedropper_history_order_redo_shortcut(),
            )
        parts = [x.strip() for x in str(text or '').replace('；', ',').split(',') if x.strip()]
        if len(parts) >= 2:
            return self.set_stale_prune_undo_eyedropper_history_order_shortcuts(
                parts[0], parts[1], persist=persist, rebind=True)
        try:
            self._flash_host_toast('格式需 撤序,重序', kind='warn', ms=1000)
        except Exception:
            pass
        return (
            self.stale_prune_undo_eyedropper_history_order_undo_shortcut(),
            self.stale_prune_undo_eyedropper_history_order_redo_shortcut(),
        )

    def _ensure_eyedropper_history_order_shortcuts(self, force: bool = False) -> bool:
        """wave72–73: 吸史撤序/重序快捷（可自定义）."""
        ok = True
        uk = self.stale_prune_undo_eyedropper_history_order_undo_shortcut()
        rk = self.stale_prune_undo_eyedropper_history_order_redo_shortcut()
        try:
            sc = getattr(self, '_eyedropper_history_order_undo_shortcut', None)
            if sc is None or force:
                if sc is not None:
                    try:
                        sc.setParent(None)
                        sc.deleteLater()
                    except Exception:
                        pass
                sc = QShortcut(QKeySequence(uk), self)
                sc.setContext(Qt.ShortcutContext.WidgetWithChildrenShortcut)
                sc.activated.connect(
                    lambda: self.undo_stale_prune_undo_eyedropper_history_reorder())
                self._eyedropper_history_order_undo_shortcut = sc
            else:
                try:
                    sc.setKey(QKeySequence(uk))
                except Exception:
                    pass
            self._last_eyedropper_history_order_undo_shortcut = uk
        except Exception:
            self._eyedropper_history_order_undo_shortcut = None
            ok = False
        try:
            sc = getattr(self, '_eyedropper_history_order_redo_shortcut', None)
            if sc is None or force:
                if sc is not None:
                    try:
                        sc.setParent(None)
                        sc.deleteLater()
                    except Exception:
                        pass
                sc = QShortcut(QKeySequence(rk), self)
                sc.setContext(Qt.ShortcutContext.WidgetWithChildrenShortcut)
                sc.activated.connect(
                    lambda: self.redo_stale_prune_undo_eyedropper_history_reorder())
                self._eyedropper_history_order_redo_shortcut = sc
            else:
                try:
                    sc.setKey(QKeySequence(rk))
                except Exception:
                    pass
            self._last_eyedropper_history_order_redo_shortcut = rk
        except Exception:
            self._eyedropper_history_order_redo_shortcut = None
            ok = False
        return ok

    def reorder_stale_prune_undo_eyedropper_history(
            self, order=None, *, persist: bool = True,
            push_undo: bool = True) -> list:
        """wave68–70: 吸管历史色拖拽排序落盘（可压撤销栈）."""
        cur = self.stale_prune_undo_eyedropper_history()
        if order is None:
            return list(cur)
        if (push_undo
                and not getattr(self, '_eyedropper_history_reorder_skip_undo_push', False)
                and list(order) != list(cur)):
            try:
                self.push_stale_prune_undo_eyedropper_history_order_undo(cur)
            except Exception:
                pass
        seen = set()
        out = []
        for c in list(order or []):
            c = str(c or '').strip()
            if not c:
                continue
            if not c.startswith('#'):
                c = '#' + c
            try:
                qc = QColor(c)
                if not qc.isValid():
                    continue
                c = qc.name()
            except Exception:
                continue
            if c in seen:
                continue
            if c not in cur:
                continue
            seen.add(c)
            out.append(c)
        for c in cur:
            if c not in seen:
                out.append(c)
        out = out[:12]
        self._stale_prune_undo_eyedropper_history = out
        if persist:
            try:
                self._host_settings().setValue(
                    'host/stalePruneUndoEyedropperHistory', list(out))
            except Exception:
                pass
        self._last_stale_prune_undo_eyedropper_history_reordered = list(out)
        self._last_stale_prune_undo_eyedropper_history = list(out)
        return list(out)

    def move_stale_prune_undo_eyedropper_history(
            self, hexv: str, new_idx: int = 0, *, persist: bool = True) -> list:
        """wave68: 移动吸管历史色到指定下标."""
        hexv = str(hexv or '').strip()
        cur = self.stale_prune_undo_eyedropper_history()
        if not hexv:
            return list(cur)
        if not hexv.startswith('#'):
            hexv = '#' + hexv
        try:
            qc = QColor(hexv)
            if not qc.isValid():
                return list(cur)
            hexv = qc.name()
        except Exception:
            return list(cur)
        if hexv not in cur:
            return list(cur)
        try:
            new_idx = int(new_idx)
        except Exception:
            new_idx = 0
        new_idx = max(0, min(len(cur) - 1, new_idx))
        cur = [x for x in cur if x != hexv]
        cur.insert(new_idx, hexv)
        return self.reorder_stale_prune_undo_eyedropper_history(cur, persist=persist)

    def apply_stale_prune_undo_eyedropper_history(
            self, hexv: str = '', which: str = 'hi', *, persist: bool = True) -> str:
        """wave66: 从历史色应用到 which."""
        hexv = str(hexv or '').strip()
        which = str(which or 'hi').strip().lower()
        if which not in ('hi', 'mid', 'lo'):
            which = 'hi'
        if not hexv:
            return ''
        if not hexv.startswith('#'):
            hexv = '#' + hexv
        try:
            c = QColor(hexv)
            if not c.isValid():
                return ''
            hexv = c.name()
        except Exception:
            return ''
        self.set_stale_prune_undo_color_custom_hex(hexv, which=which, persist=persist)
        self.remember_stale_prune_undo_eyedropper_history(hexv, persist=persist)
        self._last_stale_prune_undo_eyedropper_history_applied = hexv
        self._last_stale_prune_undo_eyedropper_history_applied_which = which
        try:
            self._paint_undo_color_scale_preview_bar()
        except Exception:
            pass
        return hexv

    def _make_undo_color_scale_eyedropper_history_row(self, parent=None, which: str = 'hi'):
        """wave66–68: 吸管历史色条（右键删 · 拖拽排序）."""
        wrap = QWidget(parent or self)
        wrap.setObjectName('hostUndoColorScaleEyedropperHistory')
        lay = QHBoxLayout(wrap)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(3)
        lab = QLabel('吸史', wrap)
        lab.setStyleSheet('color:#9aa7b5;font-size:10px;')
        lay.addWidget(lab)
        btns = []
        self._eyedropper_history_drag_hex = ''
        self._eyedropper_history_drag_btns = []
        self._eyedropper_history_drag_moved = False
        self._eyedropper_history_drag_start = None
        self._eyedropper_history_drag_target_idx = -1
        clear_slot = {'w': None}  # filled after clear btn created

        def _clear_drop_hl(sibs=None):
            for sb in list(sibs or getattr(self, '_eyedropper_history_drag_btns', []) or []):
                try:
                    hx2 = str(sb.property('undoEyedropperHistoryHex') or '')
                    if sb.property('eyedropperHistoryDropHighlight'):
                        sb.setProperty('eyedropperHistoryDropHighlight', False)
                        sb.setStyleSheet(
                            f'background:{hx2};border:1px solid #3a3d42;border-radius:2px;')
                except Exception:
                    pass

        def _set_drop_hl(target, sibs=None):
            _clear_drop_hl(sibs)
            if target is None:
                self._eyedropper_history_drag_target_idx = -1
                return
            try:
                hx2 = str(target.property('undoEyedropperHistoryHex') or '')
                target.setProperty('eyedropperHistoryDropHighlight', True)
                target.setStyleSheet(
                    f'background:{hx2};border:2px solid #f0c040;border-radius:2px;')
                sibs2 = list(sibs or getattr(self, '_eyedropper_history_drag_btns', []) or [])
                self._eyedropper_history_drag_target_idx = (
                    sibs2.index(target) if target in sibs2 else -1)
                self._last_eyedropper_history_drop_highlight_hex = hx2
            except Exception:
                pass

        def _ensure_ghost(hh):
            ghost = getattr(self, '_eyedropper_history_drag_ghost', None)
            try:
                if ghost is None:
                    ghost = QLabel(None)
                    ghost.setObjectName('hostUndoEyedropperHistoryDragGhost')
                    ghost.setProperty('isUndoEyedropperHistoryDragGhost', True)
                    ghost.setFixedSize(18, 18)
                    ghost.setWindowFlags(
                        Qt.WindowType.ToolTip
                        | Qt.WindowType.FramelessWindowHint
                        | Qt.WindowType.WindowStaysOnTopHint)
                    ghost.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
                    self._eyedropper_history_drag_ghost = ghost
                ghost.setStyleSheet(
                    f'background:{hh};border:2px solid #f0c040;border-radius:3px;')
                try:
                    ghost.setWindowOpacity(0.55)
                except Exception:
                    pass
                ghost.setProperty('eyedropperHistoryDragGhostOpacity', 0.55)
                ghost.setText('')
                self._last_eyedropper_history_drag_ghost_opacity = 0.55
                return ghost
            except Exception:
                return None

        def _move_ghost(global_pos):
            ghost = getattr(self, '_eyedropper_history_drag_ghost', None)
            if ghost is None:
                return
            try:
                from PySide6.QtCore import QPoint as _QP
                if hasattr(global_pos, 'x'):
                    ghost.move(global_pos.x() + 10, global_pos.y() + 10)
                ghost.show()
                self._last_eyedropper_history_drag_ghost_shown = True
            except Exception:
                pass

        def _hide_ghost():
            ghost = getattr(self, '_eyedropper_history_drag_ghost', None)
            if ghost is None:
                return
            try:
                ghost.hide()
            except Exception:
                pass

        def _ctx_for(btn, hx):
            def _on_ctx(pos, b=btn, hh=hx):
                try:
                    m = QMenu(b)
                    act = m.addAction(f'删除 {hh}')
                    act.setProperty('isUndoEyedropperHistoryRemove', True)
                    act.setProperty('undoEyedropperHistoryHex', hh)
                    act.triggered.connect(
                        lambda *_a, hx2=hh, bb=b: (
                            self.remove_stale_prune_undo_eyedropper_history(hx2),
                            bb.hide(),
                            setattr(self, '_last_stale_prune_undo_eyedropper_history_swatch_hidden', hx2),
                        ))
                    self._last_undo_color_scale_eyedropper_history_context = m
                    self._last_undo_color_scale_eyedropper_history_context_hex = hh
                    if getattr(self, '_stale_prune_undo_eyedropper_history_ctx_no_exec', False):
                        return
                    m.exec(b.mapToGlobal(pos))
                except Exception:
                    pass
            return _on_ctx

        for hx in self.stale_prune_undo_eyedropper_history()[:8]:
            b = QPushButton('', wrap)
            b.setFixedSize(14, 14)
            b.setProperty('isUndoEyedropperHistorySwatch', True)
            b.setProperty('undoEyedropperHistoryHex', hx)
            b.setToolTip(f'历史 · {hx} → {which} · 拖拽排序 · 右键删除')
            b.setCursor(Qt.CursorShape.OpenHandCursor)
            b.setStyleSheet(
                f'background:{hx};border:1px solid #3a3d42;border-radius:2px;')
            b.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            b.customContextMenuRequested.connect(_ctx_for(b, hx))

            def _press(e, bb=b, hh=hx):
                self._eyedropper_history_drag_hex = hh
                self._eyedropper_history_drag_start = e.pos() if hasattr(e, 'pos') else None
                self._eyedropper_history_drag_moved = False
                self._eyedropper_history_drag_target_idx = -1
                try:
                    bb.setCursor(Qt.CursorShape.ClosedHandCursor)
                except Exception:
                    pass
                try:
                    _ensure_ghost(hh)
                except Exception:
                    pass

            def _move(e, bb=b, hh=hx):
                if getattr(self, '_eyedropper_history_drag_hex', '') != hh:
                    return
                try:
                    start = getattr(self, '_eyedropper_history_drag_start', None)
                    if start is not None and hasattr(e, 'pos'):
                        if abs(e.pos().x() - start.x()) + abs(e.pos().y() - start.y()) > 3:
                            self._eyedropper_history_drag_moved = True
                except Exception:
                    self._eyedropper_history_drag_moved = True
                # ghost follow
                if getattr(self, '_eyedropper_history_drag_moved', False):
                    try:
                        gpos = bb.mapToGlobal(e.pos()) if hasattr(e, 'pos') else None
                        if gpos is not None:
                            _move_ghost(gpos)
                    except Exception:
                        pass
                try:
                    gx = bb.mapToGlobal(e.pos()).x() if hasattr(e, 'pos') else 0
                    sibs = list(getattr(self, '_eyedropper_history_drag_btns', []) or [])
                    target_idx = None
                    target_btn = None
                    for i, sib in enumerate(sibs):
                        try:
                            cx = sib.mapToGlobal(sib.rect().center()).x()
                            if abs(gx - cx) < 12:
                                target_idx = i
                                target_btn = sib
                                break
                        except Exception:
                            pass
                    if target_btn is not None and target_btn is not bb:
                        _set_drop_hl(target_btn, sibs)
                    elif target_btn is bb:
                        _clear_drop_hl(sibs)
                    if target_idx is not None:
                        cur_idx = sibs.index(bb) if bb in sibs else -1
                        if cur_idx >= 0 and cur_idx != target_idx:
                            sibs.pop(cur_idx)
                            sibs.insert(target_idx, bb)
                            self._eyedropper_history_drag_btns = sibs
                            while lay.count() > 1:
                                item = lay.takeAt(1)
                                w = item.widget()
                                if w is not None and w.property('isUndoEyedropperHistorySwatch'):
                                    lay.removeWidget(w)
                                elif w is not None and (
                                        w.property('isUndoEyedropperHistoryClear')
                                        or w is clear_slot.get('w')):
                                    lay.removeWidget(w)
                            for sb in sibs:
                                lay.addWidget(sb)
                            if clear_slot.get('w') is not None:
                                lay.addWidget(clear_slot['w'])
                            lay.addStretch(1)
                            # keep highlight on drop neighbor after reorder
                            try:
                                if 0 <= target_idx < len(sibs) and sibs[target_idx] is not bb:
                                    _set_drop_hl(sibs[target_idx], sibs)
                            except Exception:
                                pass
                except Exception:
                    pass

            def _release(e, bb=b, hh=hx, wh=which):
                moved = bool(getattr(self, '_eyedropper_history_drag_moved', False))
                drop_idx = int(getattr(self, '_eyedropper_history_drag_target_idx', -1) or -1)
                try:
                    bb.setCursor(Qt.CursorShape.OpenHandCursor)
                except Exception:
                    pass
                try:
                    _hide_ghost()
                    _clear_drop_hl()
                except Exception:
                    pass
                self._eyedropper_history_drag_hex = ''
                self._eyedropper_history_drag_target_idx = -1
                if moved:
                    order = []
                    for sb in list(getattr(self, '_eyedropper_history_drag_btns', []) or []):
                        try:
                            order.append(str(sb.property('undoEyedropperHistoryHex') or ''))
                        except Exception:
                            pass
