    def _normalize_snap_guide_recent_max_pin_key(self, key: str, fallback: str) -> str:
        """wave69: 规范化快捷键串."""
        k = str(key or '').strip() or fallback
        try:
            qs = QKeySequence(k)
            if qs.isEmpty():
                return fallback
            return qs.toString(QKeySequence.SequenceFormat.PortableText) or fallback
        except Exception:
            return fallback

    def detect_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(
            self, dec: str = None, inc: str = None) -> list:
        """wave69: 钉上限快捷冲突检测 → [{key, role, reason}, ...]."""
        d = self._normalize_snap_guide_recent_max_pin_key(
            dec if dec is not None else self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_dec_key(),
            'Ctrl+[')
        i = self._normalize_snap_guide_recent_max_pin_key(
            inc if inc is not None else self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_inc_key(),
            'Ctrl+]')
        conflicts = []
        if d == i:
            conflicts.append({
                'key': d, 'role': 'both', 'reason': '加减键相同',
            })
        reserved = {
            'Ctrl+C': '复制', 'Ctrl+V': '粘贴', 'Ctrl+X': '剪切',
            'Ctrl+Z': '撤销', 'Ctrl+Y': '重做', 'Ctrl+A': '全选',
            'Ctrl+S': '保存', 'Ctrl+O': '打开', 'Ctrl+N': '新建',
            'Ctrl+W': '关闭', 'Ctrl+Q': '退出', 'Ctrl+F': '查找',
            'Alt+F4': '关闭窗口',
        }
        for key, role in ((d, 'dec'), (i, 'inc')):
            if key in reserved:
                conflicts.append({
                    'key': key, 'role': role,
                    'reason': f'保留快捷 · {reserved[key]}',
                })
        # collide with other QShortcuts on this widget (exclude our own)
        try:
            own = {
                id(getattr(self, '_snap_guide_recent_max_pin_dec_shortcut', None)),
                id(getattr(self, '_snap_guide_recent_max_pin_inc_shortcut', None)),
            }
            for sc in self.findChildren(QShortcut):
                if id(sc) in own:
                    continue
                try:
                    sk = sc.key().toString(QKeySequence.SequenceFormat.PortableText)
                except Exception:
                    continue
                if not sk:
                    continue
                for key, role in ((d, 'dec'), (i, 'inc')):
                    if sk == key:
                        conflicts.append({
                            'key': key, 'role': role,
                            'reason': f'与已有快捷冲突 · {sk}',
                        })
        except Exception:
            pass
        # dedupe by (key, reason)
        seen = set()
        out = []
        for c in conflicts:
            sig = (c.get('key'), c.get('reason'))
            if sig in seen:
                continue
            seen.add(sig)
            out.append(c)
        self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts = list(out)
        return list(out)

    def format_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(
            self, conflicts=None) -> str:
        """wave69: 冲突提示文案."""
        conflicts = list(
            conflicts if conflicts is not None
            else self.detect_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts()
            or [])
        if not conflicts:
            txt = ''
            self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts_text = txt
            return txt
        parts = [f"{c.get('key')}（{c.get('reason')}）" for c in conflicts]
        txt = '冲突 · ' + '；'.join(parts)
        self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts_text = txt
        return txt

    def suggest_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid(
            self) -> tuple:
        """wave70: 建议无冲突的 ± 键对（优先保留默认，再试候选）."""
        candidates = [
            ('Ctrl+[', 'Ctrl+]'),
            ('Alt+-', 'Alt+='),
            ('Ctrl+Shift+[', 'Ctrl+Shift+]'),
            ('Ctrl+;', 'Ctrl+\''),
            ('Meta+[', 'Meta+]'),
            ('Alt+[', 'Alt+]'),
            ('Ctrl+9', 'Ctrl+0'),
            ('F9', 'F10'),
            ('Ctrl+F9', 'Ctrl+F10'),
            ('Shift+F9', 'Shift+F10'),
        ]
        cur = (
            self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_dec_key(),
            self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_inc_key(),
        )
        # try current first if clean
        for pair in [cur] + candidates:
            d = self._normalize_snap_guide_recent_max_pin_key(pair[0], 'Ctrl+[')
            i = self._normalize_snap_guide_recent_max_pin_key(pair[1], 'Ctrl+]')
            if d == i:
                continue
            conf = self.detect_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(d, i)
            if not conf:
                out = (d, i)
                self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid_suggest = out
                return out
        # last resort: defaults even if conflicted
        out = ('Ctrl+[', 'Ctrl+]')
        self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid_suggest = out
        return out

    def avoid_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(
            self, *, persist: bool = True) -> tuple:
        """wave70: 一键避让 — 切到无冲突键对."""
        before = (
            self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_dec_key(),
            self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_inc_key(),
        )
        before_conf = self.detect_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(
            before[0], before[1])
        sug = self.suggest_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid()
        # if current already clean, keep
        if not before_conf:
            self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoided = before
            self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid_changed = False
            try:
                self._flash_host_toast(
                    f'钉上限键无冲突 · {before[0]} / {before[1]}', kind='ok', ms=1000)
            except Exception:
                pass
            return before
        out = self.set_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_keys(
            sug[0], sug[1], persist=persist, warn=False)
        after_conf = self.detect_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(
            out[0], out[1])
        self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoided = out
        self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid_before = before
        self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid_changed = (
            out != before)
        try:
            if after_conf:
                tip = self.format_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(
                    after_conf)
                self._flash_host_toast(
                    f'避让后仍有冲突 · {out[0]} / {out[1]} · {tip}', kind='warn', ms=1800)
            else:
                self._flash_host_toast(
                    f'已避让 · {before[0]}/{before[1]} → {out[0]}/{out[1]}',
                    kind='ok', ms=1400)
        except Exception:
            pass
        # refresh avoid btn visibility
        try:
            btn = getattr(self, '_last_snap_guide_recent_max_pin_avoid', None)
            if btn is not None:
                still = bool(after_conf)
                btn.setEnabled(still)
                btn.setVisible(True)
                btn.setProperty('snapGuideRecentMaxPinKeyConflict', still)
        except Exception:
            pass
        return out

    def preview_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid(
            self) -> dict:
        """wave71: 避让预览色标 — 当前/建议键对与冲突色."""
        cur = (
            self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_dec_key(),
            self.merge_diff_fail_hist_drop_snap_guide_recent_max_pin_inc_key(),
        )
        cur_conf = self.detect_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(
            cur[0], cur[1])
        sug = self.suggest_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid()
        sug_conf = self.detect_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_conflicts(
            sug[0], sug[1])
        # 色标：冲突橙红 / 干净翠绿 / 建议失败暗红
        cur_color = '#e6a23c' if cur_conf else '#3ecf8e'
        sug_color = '#3ecf8e' if not sug_conf else '#f56c6c'
        changed = (sug != cur) and bool(cur_conf)
        out = {
            'current': {'dec': cur[0], 'inc': cur[1], 'conflict': bool(cur_conf),
                        'color': cur_color, 'label': '冲突' if cur_conf else '干净'},
            'suggested': {'dec': sug[0], 'inc': sug[1], 'conflict': bool(sug_conf),
                          'color': sug_color, 'label': '可避' if not sug_conf else '仍冲'},
            'changed': bool(changed),
            'swatch_current': cur_color,
            'swatch_suggested': sug_color,
            'tip': (
                f"当前 {cur[0]}/{cur[1]} · {'冲突' if cur_conf else '干净'}({cur_color})"
                f" → 建议 {sug[0]}/{sug[1]} · {'可避' if not sug_conf else '仍冲'}({sug_color})"
            ),
        }
        self._last_merge_diff_fail_hist_drop_snap_guide_recent_max_pin_key_avoid_preview = dict(out)
        return dict(out)

