    def export_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_shortcut_conflict_history_filtered(
            self, path: str = None, *, which: str = None, limit: int = None) -> str:
        """wave97: export which-filtered conflict history."""
        if getattr(self, '_dst_reorder_shortcut_conflict_history_filtered_export_no_dialog', False):
            smoke = getattr(self, '_dst_reorder_shortcut_conflict_history_filtered_export_smoke_path', None)
            path = str(smoke or path or '')
        wh = str(which if which is not None else self.toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_shortcut_conflict_history_which_filter() or 'all').strip().lower()
        hist = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_shortcut_conflict_history_filtered(which=wh, limit=limit)
        if not path:
            try:
                path, _ = QFileDialog.getSaveFileName(
                    self, '导出筛选冲突历史', f'dst-conflict-hist-{wh}.json', 'JSON (*.json)')
            except Exception:
                path = ''
        path = str(path or '').strip()
        if not path:
            return ''
        try:
            import json as _json
            from pathlib import Path as _Path
            payload = {
                'which_filter': wh,
                'count': len(hist),
                'history': list(hist),
            }
            _Path(path).write_text(_json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
        except Exception:
            try:
                self._flash_host_toast('DST 筛选导出失败', kind='warn', ms=800)
            except Exception:
                pass
            return ''
        self._last_dst_reorder_shortcut_conflict_history_filtered_export = path
        try:
            self._flash_host_toast(f'DST 筛选已导出 · {wh} · {len(hist)}', kind='ok', ms=900)
        except Exception:
            pass
        return path


    def show_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_dialog(
            self, *, persist: bool = True) -> list:
        """wave86: DST 自定义 TTL 拖拽排序对话框."""
        customs = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs()
        if not customs:
            try:
                self._flash_host_toast('DST自定义 · 无条目可排序', kind='warn', ms=900)
            except Exception:
                pass
            self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_shown = False
            return []
        if getattr(self, '_dst_ttl_preset_customs_reorder_no_dialog', False):
            smoke = getattr(self, '_dst_ttl_preset_customs_reorder_smoke', None)
            order = smoke if isinstance(smoke, (list, tuple)) else [c.get('ms') for c in reversed(customs)]
            out = self.reorder_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs(
                order, persist=persist)
            self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_shown = False
            try:
                self._flash_host_toast(f'DST自定义 · 已排序{len(out)}', kind='ok', ms=900)
            except Exception:
                pass
            return list(out)
        try:
            dlg = QDialog(self)
            dlg.setWindowTitle('拖拽排序 DST 自定义')
            dlg.setObjectName('hostDstClearUndoTtlPresetCustomsReorderDialog')
            dlg.setMinimumWidth(320)
            lay = QVBoxLayout(dlg)
            tip = QLabel('拖拽条目调整顺序 · 确定后写入', dlg)
            tip.setStyleSheet('color:#9aa0a6;font-size:11px;')
            lay.addWidget(tip)
            lst = QListWidget(dlg)
            lst.setObjectName('hostDstClearUndoTtlPresetCustomsReorderList')
            try:
                lst.setDragDropMode(QAbstractItemView.DragDropMode.InternalMove)
                lst.setDefaultDropAction(Qt.DropAction.MoveAction)
                lst.setDragEnabled(True)
                lst.setAcceptDrops(True)
            except Exception:
                pass
            for c in customs:
                ms = int(c.get('ms') or 0)
                lab = str(c.get('label') or f'{ms}ms')
                item = QListWidgetItem(f'{lab} · {ms}ms')
                item.setData(Qt.ItemDataRole.UserRole, ms)
                lst.addItem(item)
            lay.addWidget(lst)
            bb = QDialogButtonBox(
                QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel, dlg)
            bb.accepted.connect(dlg.accept)
            bb.rejected.connect(dlg.reject)
            lay.addWidget(bb)
            self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_shown = True
            if dlg.exec() != QDialog.DialogCode.Accepted:
                return list(customs)
            order = []
            for i in range(lst.count()):
                it = lst.item(i)
                try:
                    order.append(int(it.data(Qt.ItemDataRole.UserRole)))
                except Exception:
                    continue
            out = self.reorder_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs(
                order, persist=persist)
            try:
                self._flash_host_toast(f'DST自定义 · 已排序{len(out)}', kind='ok', ms=900)
            except Exception:
                pass
            return list(out)
        except Exception:
            return list(customs)

    def add_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
            self, ms: int, label: str = None, *, persist: bool = True) -> list:
        """wave84: 添加 DST 自定义 TTL 预设."""
        try:
            v = int(ms)
        except Exception:
            v = 8000
        v = max(0, min(600000, v))
        lab = str(label or '').strip() or (
            f'{v // 1000}秒' if v and v % 1000 == 0 else f'{v}ms')
        customs = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs()
        customs = [c for c in customs if int(c.get('ms') or -1) != v]
        customs.append({'ms': v, 'label': lab, 'custom': True})
        if len(customs) > 12:
            customs = customs[-12:]
        if persist:
            self.persist_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs(customs)
        else:
            self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs = list(customs)
        return list(customs)

    def delete_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
            self, ms: int = None, label: str = None, *, persist: bool = True) -> list:
        """wave84: 删除 DST 自定义 TTL 预设."""
        try:
            target_ms = int(ms) if ms is not None else None
        except Exception:
            target_ms = None
        lab_key = str(label or '').strip()
        customs = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs()
        keep = []
        for c in customs:
            hit = False
            if target_ms is not None and int(c.get('ms') or -1) == target_ms:
                hit = True
            elif lab_key and str(c.get('label') or '') == lab_key:
                hit = True
            if not hit:
                keep.append(c)
        if persist:
            self.persist_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs(keep)
        else:
            self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs = list(keep)
        return list(keep)

    def edit_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
            self, ms: int, new_ms: int = None, label: str = None, *, persist: bool = True) -> list:
        """wave85: 编辑 DST 自定义 TTL 预设（按原 ms 定位）."""
        try:
            old_ms = int(ms)
        except Exception:
            old_ms = -1
        customs = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs()
        found = None
        for c in customs:
            if int(c.get('ms') or -1) == old_ms:
                found = c
                break
        if found is None:
            self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom_edited = {
                'edited': False, 'ms': old_ms,
            }
            try:
                self._flash_host_toast('DST自定义 · 未找到', kind='warn', ms=800)
            except Exception:
                pass
            return list(customs)
        try:
            v = int(new_ms) if new_ms is not None else old_ms
        except Exception:
            v = old_ms
        v = max(0, min(600000, v))
        lab = str(label if label is not None else found.get('label') or '').strip() or (
            f'{v // 1000}秒' if v and v % 1000 == 0 else f'{v}ms')
        out = []
        for c in customs:
            if int(c.get('ms') or -1) == old_ms:
                out.append({'ms': v, 'label': lab, 'custom': True})
            elif int(c.get('ms') or -1) == v and v != old_ms:
                continue  # drop dup target ms
            else:
                out.append(dict(c))
        # ensure edited row present if filtered away somehow
        if not any(int(c.get('ms') or -1) == v for c in out):
            out.append({'ms': v, 'label': lab, 'custom': True})
        if persist:
            self.persist_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs(out)
        else:
            self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs = list(out)
        self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom_edited = {
            'edited': True, 'ms': old_ms, 'new_ms': v, 'label': lab,
        }
        try:
            self._flash_host_toast(f'DST自定义 · 已改→{lab}', kind='ok', ms=900)
        except Exception:
            pass
        return list(out)

    def prompt_edit_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
            self, ms: int = None, *, persist: bool = True) -> list:
        """wave85: 对话框编辑 DST 自定义 TTL 预设."""
        customs = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs()
        if not customs:
            try:
                self._flash_host_toast('DST自定义 · 无条目', kind='warn', ms=800)
            except Exception:
                pass
            return []
        try:
            target = int(ms) if ms is not None else int(customs[-1].get('ms') or 0)
        except Exception:
            target = int(customs[-1].get('ms') or 0)
        cur_row = next((c for c in customs if int(c.get('ms') or -1) == target), customs[-1])
        cur_ms = int(cur_row.get('ms') or 0)
        if getattr(self, '_dst_ttl_preset_custom_edit_no_dialog', False):
            smoke = getattr(self, '_dst_ttl_preset_custom_edit_smoke', None)
            try:
                if isinstance(smoke, dict):
                    val = int(smoke.get('ms') if smoke.get('ms') is not None else cur_ms)
                    lab = str(smoke.get('label') if smoke.get('label') is not None else cur_row.get('label') or '')
                else:
                    val = int(smoke if smoke is not None else cur_ms)
                    lab = str(cur_row.get('label') or '')
                ok = True
            except Exception:
                val, lab, ok = cur_ms, '', False
        else:
            val, ok = QInputDialog.getInt(
                self, '编辑DST自定义',
                f'原 {cur_row.get("label") or cur_ms} → 新毫秒:',
                int(cur_ms), 0, 600000, 100)
            lab = str(cur_row.get('label') or '')
            if ok:
                try:
                    lab2, ok2 = QInputDialog.getText(
                        self, '编辑DST自定义', '标签(可空):', text=lab)
                    if ok2:
                        lab = lab2
                except Exception:
                    pass
        if not ok:
            return list(customs)
        return self.edit_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
            cur_ms, val, lab or None, persist=persist)

    def prompt_add_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
            self, *, persist: bool = True) -> list:
        """wave84: 对话框添加 DST 自定义 TTL 预设."""
        cur = self.toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms()
        if getattr(self, '_dst_ttl_preset_custom_no_dialog', False):
            smoke = getattr(self, '_dst_ttl_preset_custom_smoke', None)
            try:
                if isinstance(smoke, dict):
                    val = int(smoke.get('ms') or cur)
                    lab = str(smoke.get('label') or '')
                else:
                    val = int(smoke if smoke is not None else cur)
                    lab = ''
                ok_d = True
            except Exception:
                val, lab, ok_d = cur, '', False
        else:
            val, ok_d = QInputDialog.getInt(
                self, 'DST TTL 自定义', '毫秒:', int(cur or 8000), 0, 600000, 100)
            lab = ''
            if ok_d:
                try:
                    lab, ok2 = QInputDialog.getText(
                        self, 'DST TTL 自定义', '标签(可空):')
                    if not ok2:
                        lab = ''
                except Exception:
                    lab = ''
        if not ok_d:
            return self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs()
        return self.add_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
            val, lab or None, persist=persist)

    def list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_presets(
            self) -> list:
        """wave83–84: DST 撤清 TTL 预设档（内置 + 自定义）."""
        presets = [
            {'ms': 0, 'label': '不超时'},
            {'ms': 3000, 'label': '3秒'},
            {'ms': 8000, 'label': '8秒'},
            {'ms': 15000, 'label': '15秒'},
            {'ms': 30000, 'label': '30秒'},
            {'ms': 60000, 'label': '60秒'},
        ]
        try:
            customs = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs()
        except Exception:
            customs = []
        seen = {int(p['ms']) for p in presets}
        for c in customs:
            ms = int(c.get('ms') or 0)
            if ms in seen:
                continue
            seen.add(ms)
            presets.append({
                'ms': ms,
                'label': str(c.get('label') or f'{ms}ms'),
                'custom': True,
            })
        self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_presets = list(presets)
        return list(presets)

    def apply_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset(
            self, ms: int = 8000, *, persist: bool = True) -> int:
        """wave83: 应用 DST 撤清 TTL 预设档."""
        try:
            v = int(ms)
        except Exception:
            v = 8000
        out = self.set_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms(
            v, persist=persist)
        lab = {0: '不超时', 3000: '3秒', 8000: '8秒', 15000: '15秒', 30000: '30秒', 60000: '60秒'}.get(out, f'{out}ms')
        try:
            self._flash_host_toast(f'DST撤清TTL档 · {lab}', kind='ok', ms=900)
        except Exception:
            pass
        self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_applied = out
        return out

    def show_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_menu(
            self, global_pos=None, *, persist: bool = True) -> int:
        """wave83: DST 撤清 TTL 预设菜单."""
        presets = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_presets()
        cur = self.toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms()
        if getattr(self, '_dst_clear_undo_ttl_preset_menu_no_exec', False):
            smoke = getattr(self, '_dst_clear_undo_ttl_preset_menu_smoke', None)
            self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_menu = {
                'presets': list(presets), 'current': int(cur), 'executed': False,
            }
            if isinstance(smoke, dict):
                action = str(smoke.get('action') or '')
                if action == 'add_custom':
                    self._dst_ttl_preset_custom_no_dialog = True
                    self._dst_ttl_preset_custom_smoke = smoke
                    try:
                        customs = self.prompt_add_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
                            persist=persist)
                    finally:
                        self._dst_ttl_preset_custom_no_dialog = False
                        self._dst_ttl_preset_custom_smoke = None
                    return len(customs)
                if action == 'delete_custom':
                    customs = self.delete_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
                        smoke.get('ms'), smoke.get('label'), persist=persist)
                    return len(customs)
                if action == 'edit_custom':
                    self._dst_ttl_preset_custom_edit_no_dialog = True
                    self._dst_ttl_preset_custom_edit_smoke = smoke
                    try:
                        customs = self.prompt_edit_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
                            ms=smoke.get('ms') if smoke.get('old_ms') is None else smoke.get('old_ms'),
                            persist=persist)
                    finally:
                        self._dst_ttl_preset_custom_edit_no_dialog = False
                        self._dst_ttl_preset_custom_edit_smoke = None
                    return len(customs)
                if action == 'list_customs':
                    return len(self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs())
                if action == 'reorder_customs':
                    order = smoke.get('order')
                    self._dst_ttl_preset_customs_reorder_no_dialog = True
                    self._dst_ttl_preset_customs_reorder_smoke = order
                    try:
                        out = self.show_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_dialog(
                            persist=persist)
                    finally:
                        self._dst_ttl_preset_customs_reorder_no_dialog = False
                        self._dst_ttl_preset_customs_reorder_smoke = None
                    return len(out)
                if action == 'prompt':
                    return int(self.prompt_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms(
                        persist=persist) or 0)
                if action == 'apply' or smoke.get('ms') is not None:
                    ms = int(smoke.get('ms') if smoke.get('ms') is not None else 8000)
                    return int(self.apply_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset(
                        ms, persist=persist) or 0)
            elif smoke is not None:
                try:
                    return int(self.apply_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset(
                        int(smoke), persist=persist) or 0)
                except Exception:
                    pass
            return len(presets)
        menu = QMenu(self)
        menu.setObjectName('hostDstClearUndoTtlPresetMenu')
        menu.setProperty('isDstClearUndoTtlPresetMenu', True)
        for row in presets:
            ms = int(row.get('ms') or 0)
            lab = str(row.get('label') or f'{ms}ms')
            mark = '● ' if ms == int(cur) else '○ '
            if row.get('custom'):
                lab = '★ ' + lab
            act = QAction(mark + lab, menu)
            act.setProperty('isDstClearUndoTtlPreset', True)
            act.setProperty('dstClearUndoTtlPresetMs', ms)
            act.setProperty('dstClearUndoTtlPresetCustom', bool(row.get('custom')))
            act.triggered.connect(
                lambda *_a, mm=ms: self.apply_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset(
                    mm, persist=persist))
            menu.addAction(act)
        menu.addSeparator()
        act_p = QAction('自定义…', menu)
        act_p.triggered.connect(
            lambda *_: self.prompt_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms(
                persist=persist))
        menu.addAction(act_p)
        act_add = QAction('添加自定义档…', menu)
        act_add.setProperty('isDstClearUndoTtlPresetCustomAdd', True)
        act_add.triggered.connect(
            lambda *_: self.prompt_add_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
                persist=persist))
        menu.addAction(act_add)
        act_ord = QAction('拖拽排序…', menu)
        act_ord.setProperty('isDstClearUndoTtlPresetCustomsReorder', True)
        try:
            _nc = len(self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs())
        except Exception:
            _nc = 0
        act_ord.setEnabled(_nc > 1)
        act_ord.triggered.connect(
            lambda *_a, _p=persist: self.show_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_dialog(
                persist=_p))
        menu.addAction(act_ord)
        # wave87: DST 排序撤/重做（对齐 jitter）
        try:
            _ud = int(self.toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_undo_depth())
        except Exception:
            _ud = 0
        try:
            _rd = int(self.toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_redo_depth())
        except Exception:
            _rd = 0
        act_ordu = QAction(f'撤销排序 · {_ud}', menu)
        act_ordu.setProperty('isDstClearUndoTtlPresetCustomsReorderUndo', True)
        act_ordu.setProperty('dstClearUndoTtlPresetCustomsReorderUndoDepth', int(_ud))
        act_ordu.setEnabled(bool(_ud))
        act_ordu.triggered.connect(
            lambda *_: self.undo_reorder_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs())
        menu.addAction(act_ordu)
        act_ordr = QAction(f'重做排序 · {_rd}', menu)
        act_ordr.setProperty('isDstClearUndoTtlPresetCustomsReorderRedo', True)
        act_ordr.setProperty('dstClearUndoTtlPresetCustomsReorderRedoDepth', int(_rd))
        act_ordr.setEnabled(bool(_rd))
        act_ordr.triggered.connect(
            lambda *_: self.redo_reorder_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs())
        menu.addAction(act_ordr)
        act_ordc = QAction(f'清重做栈 · {_rd}', menu)
        act_ordc.setProperty('isDstClearUndoTtlPresetCustomsReorderClearRedo', True)
        act_ordc.setEnabled(bool(_rd))
        act_ordc.triggered.connect(
            lambda *_: self.clear_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs_reorder_redo())
        menu.addAction(act_ordc)
        # wave85: 自定义编辑/删项
        try:
            customs_m = self.list_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_customs()
        except Exception:
            customs_m = []
        if customs_m:
            menu.addSeparator()
            for crow in customs_m:
                cms = int(crow.get('ms') or 0)
                clab = str(crow.get('label') or f'{cms}ms')
                act_e = QAction(f'✏ {clab}', menu)
                act_e.setProperty('isDstClearUndoTtlPresetCustomEdit', True)
                act_e.setProperty('dstTtlPresetCustomMs', cms)
                act_e.triggered.connect(
                    lambda *_a, mm=cms, _p=persist: self.prompt_edit_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
                        ms=mm, persist=_p))
                menu.addAction(act_e)
                act_d = QAction(f'🗑 {clab}', menu)
                act_d.setProperty('isDstClearUndoTtlPresetCustomDelete', True)
                act_d.setProperty('dstTtlPresetCustomMs', cms)
                act_d.triggered.connect(
                    lambda *_a, mm=cms, _p=persist: self.delete_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_custom(
                        ms=mm, persist=_p))
                menu.addAction(act_d)
        self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_preset_menu_widget = menu
        try:
            if global_pos is not None:
                menu.exec(global_pos)
            else:
                menu.exec(self.mapToGlobal(self.rect().center()))
        except Exception:
            pass
        return len(presets)

    def prompt_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms(
            self, *, persist: bool = True) -> int:
        """wave82: 对话框设定 DST 撤清 TTL."""
        cur = self.toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms()
        if getattr(self, '_dst_clear_undo_ttl_no_dialog', False):
            smoke = getattr(self, '_dst_clear_undo_ttl_smoke', None)
            try:
                val = int(smoke if smoke is not None else cur)
                ok = True
            except Exception:
                val, ok = cur, False
        else:
            val, ok = QInputDialog.getInt(
                self, 'DST撤清TTL',
                '超时毫秒 (0=不超时):',
                int(cur), 0, 600000, 100)
        if not ok:
            return cur
        return self.set_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms(
            val, persist=persist)

    def discard_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap(
            self, *, reason: str = 'ttl', toast: bool = True) -> int:
        """wave82: 丢弃 DST 撤清快照."""
        snap = list(getattr(
            self,
            '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap',
            []) or [])
        n = len(snap)
        self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap = []
        try:
            t = getattr(
                self,
                '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_timer',
                None)
            if t is not None:
                t.stop()
        except Exception:
            pass
        try:
            self._refresh_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ui(0)
        except Exception:
            pass
        self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap_discarded = {
            'discarded': int(n), 'reason': str(reason or ''),
        }
        if toast and n:
            try:
                self._flash_host_toast(
                    f'DST撤清快照 · 已丢{n} · {reason}', kind='warn', ms=900)
            except Exception:
                pass
        return int(n)

    def _schedule_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_expire(
            self) -> int:
        """wave82: 安排 DST 撤清快照超时丢弃."""
        ttl = self.toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_ms()
        try:
            t = getattr(
                self,
                '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_timer',
                None)
            if t is None:
                t = QTimer(self)
                t.setSingleShot(True)
                t.timeout.connect(
                    lambda: self.discard_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap(
                        reason='ttl', toast=True))
                self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_timer = t
            t.stop()
            snap = getattr(
                self,
                '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap',
                None)
            if ttl > 0 and snap:
                t.start(int(ttl))
        except Exception:
            pass
        self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ttl_scheduled = int(ttl)
        return int(ttl)

    def clear_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo(
            self, *, toast: bool = True) -> int:
        """wave80–81: 清空 DST 全应用撤销栈（可撤销清栈）."""
        stack = list(getattr(
            self,
            '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo',
            []) or [])
        nclear = len(stack)
        if nclear:
            self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap = list(stack)
            try:
                self._schedule_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_expire()
            except Exception:
                pass
        self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo = []
        try:
            self._refresh_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_depth_ui(0)
        except Exception:
            pass
        try:
            self._refresh_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ui(nclear)
        except Exception:
            pass
        self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_cleared = {
            'cleared': nclear, 'undoable': bool(nclear),
        }
        if toast:
            try:
                self._flash_host_toast(
                    f'DST撤栈 · 已清{nclear} · 可撤清' if nclear else 'DST撤栈已空',
                    kind='ok' if nclear else 'warn', ms=900)
            except Exception:
                pass
        return int(nclear)

    def toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_depth(
            self) -> int:
        """wave81: 可撤清快照深度."""
        snap = list(getattr(
            self,
            '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap',
            []) or [])
        return len(snap)

    def _refresh_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ui(
            self, depth: int = None) -> int:
        """wave81: 刷新 DST 可撤清提示（旁标 tip）."""
        try:
            d = int(depth) if depth is not None else self.toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_depth()
        except Exception:
            d = 0
        d = max(0, d)
        try:
            lab = getattr(
                self,
                '_last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_depth_lab',
                None)
            if lab is not None:
                tip = str(lab.toolTip() or '')
                if ' · 可撤清' in tip:
                    tip = tip.split(' · 可撤清')[0]
                if d > 0:
                    tip = tip + f' · 可撤清{d}(中键)'
                lab.setToolTip(tip)
                lab.setProperty(
                    'toastCurvePngDatetimeTzDstYearRangeRecentApplyAllUndoClearUndoDepth', int(d))
        except Exception:
            pass
        return int(d)

    def undo_clear_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo(
            self, *, toast: bool = True) -> int:
        """wave81: 撤销 DST 清栈 · 恢复快照."""
        snap = list(getattr(
            self,
            '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap',
            []) or [])
        if not snap:
            self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undone = {
                'restored': 0, 'undone': False,
            }
            if toast:
                try:
                    self._flash_host_toast('DST · 无可撤清', kind='warn', ms=800)
                except Exception:
                    pass
            return 0
        self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo = list(snap)
        self._toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_snap = []
        try:
            t = getattr(
                self,
                '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_timer',
                None)
            if t is not None:
                t.stop()
        except Exception:
            pass
        depth = len(snap)
        try:
            self._refresh_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_depth_ui(depth)
        except Exception:
            pass
        try:
            self._refresh_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undo_ui(0)
        except Exception:
            pass
        self._last_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_clear_undone = {
            'restored': int(depth), 'undone': True,
        }
        if toast:
            try:
                self._flash_host_toast(f'DST · 已撤清 · 恢复{depth}', kind='ok', ms=1000)
            except Exception:
                pass
        return int(depth)

    def toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_long_press_ms(self) -> int:
        """wave80: DST 深度旁标长按清栈阈值."""
        try:
            v = int(getattr(
                self,
                '_toast_curve_png_datetime_tz_city_dst_calendar_year_range_recent_apply_all_undo_long_press_ms',
                650) or 650)
        except Exception:
            v = 650
        return max(200, min(3000, v))


