            row_ex.addWidget(btn_save)
            row_ex.addWidget(btn_copy)
            row_ex.addWidget(btn_recent)
            row_ex.addStretch(1)
            lay.addLayout(row_ex)

            def _do_save():
                self.export_toast_hist_cap_tip_anim_curve_clipboard_preview_png()

